/** Complete AMOLED Android player: local library, online search/streaming, downloads and controls. */
class FinalPlayerActivity : AppCompatActivity() {
    private val bg=Color.rgb(6,6,10); private val card=Color.rgb(15,15,23); private val card2=Color.rgb(23,22,32)
    private val white=Color.rgb(246,244,252); private val muted=Color.rgb(151,146,166); private val violet=Color.rgb(123,81,251); private val border=Color.rgb(43,40,58)
    private lateinit var page:FrameLayout; private lateinit var miniTitle:TextView; private lateinit var miniArtist:TextView; private lateinit var miniPlay:TextView
    private var local:List<LocalTrack> = emptyList(); private val ui=Handler(Looper.getMainLooper()); private val store by lazy{UserMusicStore(this)}
    private var sleep:Runnable?=null; private var sleepEnd=0L
    private fun dp(v:Int)=(v*resources.displayMetrics.density+.5f).toInt()
    private fun tv(s:String,z:Float,c:Int=white,b:Boolean=false)=TextView(this).apply{text=s;textSize=z;setTextColor(c);includeFontPadding=false;if(b)typeface=Typeface.DEFAULT_BOLD}
    private fun box(c:Int=card,r:Int=17,stroke:Boolean=false)=android.graphics.drawable.GradientDrawable().apply{setColor(c);cornerRadius=dp(r).toFloat();if(stroke)setStroke(dp(1),border)}
    private fun grad(r:Int=18)=android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,intArrayOf(Color.rgb(55,34,112),violet)).apply{cornerRadius=dp(r).toFloat()}
    override fun onCreate(b:Bundle?){super.onCreate(b);window.statusBarColor=bg;window.navigationBarColor=bg;requestPermissionsIfNeeded();PlaybackController.connect(this);local=scan();restoreTimer();build();home()}
    private fun scan()=runCatching{LocalMusicScanner.scan(this)}.getOrElse{emptyList()}
    private fun requestPermissionsIfNeeded(){val p=if(Build.VERSION.SDK_INT>=33)Manifest.permission.READ_MEDIA_AUDIO else Manifest.permission.READ_EXTERNAL_STORAGE;if(ContextCompat.checkSelfPermission(this,p)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,arrayOf(p),44);if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,arrayOf(Manifest.permission.POST_NOTIFICATIONS),45)}
    private fun build(){val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(bg)};root.addView(header(),LinearLayout.LayoutParams(-1,dp(61)));page=FrameLayout(this);root.addView(page,LinearLayout.LayoutParams(-1,0,1f));root.addView(mini(),LinearLayout.LayoutParams(-1,dp(70)).apply{setMargins(dp(9),dp(5),dp(9),dp(5))});root.addView(nav(),LinearLayout.LayoutParams(-1,dp(63)).apply{setMargins(dp(8),0,dp(8),dp(5))});setContentView(root)}
    private fun header()=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;setPadding(dp(14),dp(7),dp(14),dp(4));addView(tv("S",18f,Color.WHITE,true).apply{gravity=Gravity.CENTER;background=grad(11)},LinearLayout.LayoutParams(dp(36),dp(36)));addView(tv("Spotifusion",18f,white,true).apply{setPadding(dp(10),0,0,0)},LinearLayout.LayoutParams(0,-1,1f));addView(tv("⌕",25f,white,true).apply{gravity=Gravity.CENTER;background=box(card2,15,true);setOnClickListener{search()}},LinearLayout.LayoutParams(dp(44),dp(44)).apply{rightMargin=dp(7)});addView(tv("⋮",24f,white,true).apply{gravity=Gravity.CENTER;background=box(card2,15,true);setOnClickListener{settings()}},LinearLayout.LayoutParams(dp(44),dp(44)))}
    private fun nav()=LinearLayout(this).apply{gravity=Gravity.CENTER;background=box(card,21,true);setPadding(dp(3),dp(3),dp(3),dp(3));listOf("⌂" to "Home","⌕" to "Search","▣" to "Library","≋" to "EQ").forEachIndexed{i,x->val v=LinearLayout(this@FinalPlayerActivity).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setOnClickListener{when(i){0->home();1->search();2->library();3->eq()}}};v.addView(tv(x.first,18f,if(i==0)violet else muted,true).apply{gravity=Gravity.CENTER});v.addView(tv(x.second,9f,if(i==0)violet else muted,true).apply{gravity=Gravity.CENTER;setPadding(0,dp(3),0,0)});addView(v,LinearLayout.LayoutParams(0,-1,1f))}}
    private fun mini()=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;background=box(card,17,true);setPadding(dp(7),dp(6),dp(7),dp(6));val art=ImageView(this@FinalPlayerActivity).apply{setImageResource(android.R.drawable.ic_media_play);background=grad(12);setPadding(dp(12),dp(12),dp(12),dp(12))};addView(art,LinearLayout.LayoutParams(dp(48),dp(48)));val info=LinearLayout(this@FinalPlayerActivity).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(10),0,dp(5),0);setOnClickListener{player()}};miniTitle=tv(PlaybackController.currentTitle().ifBlank{"Nothing playing"},12.5f,white,true);miniArtist=tv(PlaybackController.currentArtist().ifBlank{"Choose a song"},10f,muted);info.addView(miniTitle);info.addView(miniArtist.apply{setPadding(0,dp(4),0,0)});addView(info,LinearLayout.LayoutParams(0,-1,1f));addView(tv("♥",20f,muted).apply{gravity=Gravity.CENTER},LinearLayout.LayoutParams(dp(40),dp(48)));miniPlay=tv(if(PlaybackController.isPlaying())"Ⅱ" else "▶",18f,white,true).apply{gravity=Gravity.CENTER;setOnClickListener{PlaybackController.toggle();refreshMini()}};addView(miniPlay,LinearLayout.LayoutParams(dp(44),dp(48)))}
    private fun refreshMini(){if(!::miniTitle.isInitialized)return;miniTitle.text=PlaybackController.currentTitle().ifBlank{"Nothing playing"};miniArtist.text=PlaybackController.currentArtist().ifBlank{"Choose a song"};miniPlay.text=if(PlaybackController.isPlaying())"Ⅱ" else "▶"}
    private fun page(c:LinearLayout){val s=ScrollView(this).apply{setBackgroundColor(bg);isFillViewport=true};s.addView(c,FrameLayout.LayoutParams(-1,-1));page.removeAllViews();page.addView(s,FrameLayout.LayoutParams(-1,-1))}
    private fun col()=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(7),dp(14),dp(28))}
    private fun section(c:LinearLayout,s:String){c.addView(tv(s,14f,white,true).apply{setPadding(0,dp(15),0,dp(9))})}
    private fun home(){val c=col();c.addView(tv("Good evening",11f,muted));c.addView(tv("Your sound. Your space.",25f,white,true).apply{setPadding(0,dp(5),0,dp(14))});val h=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;background=grad(22);setPadding(dp(14),dp(13),dp(12),dp(13))};h.addView(tv("◉",51f,Color.WHITE,true).apply{gravity=Gravity.CENTER;background=box(Color.rgb(53,35,112),17)},LinearLayout.LayoutParams(dp(106),dp(106)));val x=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(13),0,0,0)};x.addView(tv("YOUR LIBRARY",9f,Color.WHITE,true));val first=local.firstOrNull();x.addView(tv(first?.title?:"Add your music",17f,Color.WHITE,true).apply{setPadding(0,dp(7),0,dp(4));maxLines=1});x.addView(tv(first?.artist?:"Local music on this device",10f,Color.rgb(224,216,255)).apply{setPadding(0,0,0,dp(10))});x.addView(tv("  PLAY NOW  ",10f,violet,true).apply{gravity=Gravity.CENTER;background=box(Color.WHITE,14);setPadding(dp(4),dp(8),dp(4),dp(8));setOnClickListener{if(local.isNotEmpty())playLocal(0)}});h.addView(x,LinearLayout.LayoutParams(0,-2,1f));c.addView(h,LinearLayout.LayoutParams(-1,dp(132)));section(c,"Recently played");val recent=store.recentlyPlayed().ifEmpty{local};recent.take(10).forEach{tr->row(c,tr)};section(c,"Quick actions");val q=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};action(q,"♥","Liked"){favorites()};action(q,"▤","Playlists"){startActivity(android.content.Intent(this@FinalPlayerActivity,PlaylistActivity::class.java))};action(q,"◷","Timer"){timerDialog()};c.addView(q,LinearLayout.LayoutParams(-1,dp(84)));page(c)}
    private fun action(p:LinearLayout,i:String,s:String,a:()->Unit){val v=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;background=box(card,15,true);setOnClickListener{a()}};v.addView(tv(i,21f,violet,true));v.addView(tv(s,9f,muted,true).apply{setPadding(0,dp(4),0,0)});p.addView(v,LinearLayout.LayoutParams(0,-1,1f).apply{setMargins(dp(3),0,dp(3),0)})}
    private fun row(p:LinearLayout,tr:LocalTrack){val r=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;background=box(card,14,true);setPadding(dp(7),dp(6),dp(7),dp(6));setOnClickListener{playTrack(tr)}};val art=ImageView(this).apply{scaleType=ImageView.ScaleType.CENTER_CROP;setImageBitmap(ArtworkResolver.load(this@FinalPlayerActivity,tr.albumId,128));background=grad(11)};r.addView(art,LinearLayout.LayoutParams(dp(46),dp(46)));val x=LinearLayout(this@FinalPlayerActivity).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(10),0,dp(5),0)};x.addView(tv(tr.title,12f,white,true).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END});x.addView(tv(tr.artist,9.5f,muted).apply{setPadding(0,dp(4),0,0)});r.addView(x,LinearLayout.LayoutParams(0,-2,1f));r.addView(tv(if(store.isFavorite(tr.id))"♥" else "♡",18f,if(store.isFavorite(tr.id))violet else muted).apply{setOnClickListener{store.toggleFavorite(tr.id);home()}});p.addView(r,LinearLayout.LayoutParams(-1,dp(62)).apply{bottomMargin=dp(6)})}
    private fun playTrack(tr:LocalTrack){PlaybackController.playTracks(local,local.indexOfFirst{it.id==tr.id}.coerceAtLeast(0));store.addRecentlyPlayed(tr);refreshMini()}
    private fun playLocal(i:Int){if(local.isNotEmpty()){val tr=local[i.coerceIn(0,local.lastIndex)];PlaybackController.playTracks(local,i);store.addRecentlyPlayed(tr);refreshMini()}}
    private fun search(){val c=col();c.addView(tv("Search",26f,white,true).apply{setPadding(0,dp(5),0,dp(12))});val e=EditText(this).apply{hint="Search songs, artists, albums";setHintTextColor(muted);setTextColor(white);textSize=14f;singleLine=true;background=box(card2,16,true);setPadding(dp(14),0,dp(14),0)};c.addView(e,LinearLayout.LayoutParams(-1,dp(52)));val out=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(out);fun run(q:String){if(q.length<2){out.removeAllViews();out.addView(tv("Type at least 2 characters",11f,muted).apply{setPadding(0,dp(16),0,0)});return};out.removeAllViews();out.addView(tv("Searching YouTube…",11f,muted).apply{setPadding(0,dp(16),0,dp(8))});Thread{try{val u="https://spotifusion.onrender.com/api/search?query="+URLEncoder.encode(q,"UTF-8")+"&limit=30";val conn=URL(u).openConnection() as HttpURLConnection;conn.connectTimeout=10000;conn.readTimeout=20000;val json=JSONObject(conn.inputStream.bufferedReader().use{it.readText()});val a=json.optJSONArray("results");ui.post{out.removeAllViews();if(a==null||a.length()==0)out.addView(tv("No online results",11f,muted))else for(k in 0 until a.length())onlineRow(out,a.getJSONObject(k))}}catch(_:Exception){ui.post{out.removeAllViews();out.addView(tv("Online search unavailable. Check your connection.",11f,muted))}}}.start()};e.addTextChangedListener{run(it?.toString()?.trim().orEmpty())};page(c)}
    private fun onlineRow(p:LinearLayout,o:JSONObject){val id=o.optString("videoId");val title=o.optString("title","Unknown");val artist=o.optString("artist","Unknown Artist");val thumb=o.optString("thumbnail");val r=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;background=box(card,14,true);setPadding(dp(7),dp(6),dp(7),dp(6))};val im=ImageView(this).apply{scaleType=ImageView.ScaleType.CENTER_CROP;background=grad(11)};loadImage(im,thumb);r.addView(im,LinearLayout.LayoutParams(dp(52),dp(52)));val x=LinearLayout(this@FinalPlayerActivity).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(10),0,dp(3),0)};x.addView(tv(title,12f,white,true).apply{maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END});x.addView(tv(artist,9.5f,muted).apply{setPadding(0,dp(4),0,0)});r.addView(x,LinearLayout.LayoutParams(0,-2,1f));r.addView(tv("▶",12f,violet,true).apply{setOnClickListener{streamOnline(id,title,artist,thumb)}});r.addView(tv("⇩",17f,violet,true).apply{setPadding(dp(10),0,dp(7),0);setOnClickListener{resolveForDownload(id,title)}});p.addView(r,LinearLayout.LayoutParams(-1,dp(68)).apply{bottomMargin=dp(6)})}
    private fun loadImage(v:ImageView,u:String){if(u.isBlank())return;Thread{runCatching{BitmapFactory.decodeStream(URL(u).openStream())}.getOrNull()?.let{b->ui.post{v.setImageBitmap(b)}}}.start()}
    private fun streamOnline(id:String,title:String,artist:String,thumb:String){if(id.isBlank())return;Thread{try{val c=URL("https://spotifusion.onrender.com/api/stream/$id").openConnection() as HttpURLConnection;c.connectTimeout=10000;c.readTimeout=20000;val o=JSONObject(c.inputStream.bufferedReader().use{it.readText()});val u=o.optString("url");ui.post{if(u.isBlank())toast("Stream unavailable")else{PlaybackController.play(u,title,artist,"YouTube",id,thumb);refreshMini();toast("Playing online")}}}catch(_:Exception){ui.post{toast("Online stream unavailable")}}}.start()}
    private fun resolveForDownload(id:String,title:String){Thread{try{val c=URL("https://spotifusion.onrender.com/api/stream/$id").openConnection() as HttpURLConnection;c.connectTimeout=10000;c.readTimeout=20000;val u=JSONObject(c.inputStream.bufferedReader().use{it.readText()}).optString("url");ui.post{if(u.isBlank())toast("Download unavailable")else download(u,title)}}catch(_:Exception){ui.post{toast("Download service unavailable")}}}.start()}
    private fun download(url:String,title:String){val dm=getSystemService(DOWNLOAD_SERVICE) as DownloadManager;val req=DownloadManager.Request(Uri.parse(url)).setTitle(title).setDescription("Spotifusion offline download").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setAllowedOverMetered(true).setAllowedOverRoaming(false);if(Build.VERSION.SDK_INT>=29)req.setDestinationInExternalPublicDir(android.os.Environment.DIRECTORY_MUSIC,"Spotifusion/$title.m4a");else req.setDestinationInExternalPublicDir(android.os.Environment.DIRECTORY_MUSIC,"Spotifusion/$title.m4a");dm.enqueue(req);toast("Download started")}
    private fun library(){val c=col();c.addView(tv("Library",26f,white,true));libraryCard(c,"Local Music","${local.size} tracks","♫"){home()};libraryCard(c,"Liked songs","${store.favoriteIds().size} saved","♥"){favorites()};libraryCard(c,"Playlists","Create, add, remove and play","▤"){startActivity(android.content.Intent(this,PlaylistActivity::class.java))};libraryCard(c,"Downloads","Saved to Music/Spotifusion","⇩"){toast("Open your Music folder to see completed downloads")};page(c)}
    private fun libraryCard(c:LinearLayout,a:String,b:String,i:String,click:()->Unit){val r=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;background=box(card,17,true);setPadding(dp(12),dp(10),dp(12),dp(10));setOnClickListener{click()}};r.addView(tv(i,22f,violet,true).apply{gravity=Gravity.CENTER;background=box(Color.rgb(29,22,48),13)},LinearLayout.LayoutParams(dp(48),dp(48)));val x=LinearLayout(this@FinalPlayerActivity).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(11),0,0,0)};x.addView(tv(a,12.5f,white,true));x.addView(tv(b,9.5f,muted).apply{setPadding(0,dp(5),0,0)});r.addView(x,LinearLayout.LayoutParams(0,-2,1f));r.addView(tv("›",23f,muted));c.addView(r,LinearLayout.LayoutParams(-1,dp(72)).apply{bottomMargin=dp(8)})}
    private fun favorites(){val c=col();c.addView(tv("Liked songs",25f,white,true));val fav=local.filter{store.isFavorite(it.id)};c.addView(tv("${fav.size} songs · stored only on this device",10f,muted).apply{setPadding(0,dp(5),0,dp(12))});fav.forEach{row(c,it)};if(fav.isEmpty())c.addView(tv("Tap ♡ beside a local song to save it here.",11f,muted).apply{setPadding(0,dp(20),0,0)});page(c)}
    private fun player(){val c=col();c.gravity=Gravity.CENTER_HORIZONTAL;c.addView(tv("NOW PLAYING",10f,violet,true));val cur=local.firstOrNull{it.id.toString()==PlaybackController.currentMediaId()};val art=ImageView(this).apply{scaleType=ImageView.ScaleType.CENTER_CROP;background=grad(25);setImageBitmap(cur?.let{ArtworkResolver.load(this@FinalPlayerActivity,it.albumId,512)})};c.addView(art,LinearLayout.LayoutParams(dp(250),dp(250)));c.addView(tv(PlaybackController.currentTitle().ifBlank{"Nothing playing"},22f,white,true).apply{gravity=Gravity.CENTER;setPadding(0,dp(17),0,dp(4))});c.addView(tv(PlaybackController.currentArtist().ifBlank{"Select a track"},12f,muted));val seek=SeekBar(this).apply{max=1000;progressTintList=android.content.res.ColorStateList.valueOf(violet);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,u:Boolean){if(u)PlaybackController.seek((PlaybackController.duration()*p/1000f).toLong())};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){} })};c.addView(seek,LinearLayout.LayoutParams(-1,dp(42)));val times=LinearLayout(this).apply{gravity=Gravity.CENTER};times.addView(tv(formatTime(PlaybackController.position()),10f,muted),LinearLayout.LayoutParams(0,dp(24),1f));times.addView(tv(formatTime(PlaybackController.duration()),10f,muted).apply{gravity=Gravity.RIGHT},LinearLayout.LayoutParams(0,dp(24),1f));c.addView(times);val controls=LinearLayout(this).apply{gravity=Gravity.CENTER};controls.addView(tv("↶",25f,white,true).apply{setOnClickListener{PlaybackController.previous();refreshMini();player()}},LinearLayout.LayoutParams(dp(65),dp(60)));controls.addView(tv(if(PlaybackController.isPlaying())"Ⅱ" else "▶",30f,Color.WHITE,true).apply{gravity=Gravity.CENTER;background=grad(60);setOnClickListener{PlaybackController.toggle();player();refreshMini()}},LinearLayout.LayoutParams(dp(70),dp(70)));controls.addView(tv("↷",25f,white,true).apply{setOnClickListener{PlaybackController.next();refreshMini();player()}},LinearLayout.LayoutParams(dp(65),dp(60)));c.addView(controls);val opts=LinearLayout(this).apply{gravity=Gravity.CENTER};val sh=tv(if(PlaybackController.isShuffleEnabled())"SHUFFLE ON" else "SHUFFLE",10f,if(PlaybackController.isShuffleEnabled())violet else muted,true).apply{setOnClickListener{PlaybackController.setShuffle(!PlaybackController.isShuffleEnabled());player()}};val rep=tv(if(PlaybackController.isRepeatEnabled())"REPEAT ONE" else "REPEAT",10f,if(PlaybackController.isRepeatEnabled())violet else muted,true).apply{setOnClickListener{PlaybackController.setRepeat(!PlaybackController.isRepeatEnabled());player()}};opts.addView(sh,LinearLayout.LayoutParams(0,dp(48),1f));opts.addView(tv("LYRICS",10f,muted,true).apply{setOnClickListener{startActivity(android.content.Intent(this@FinalPlayerActivity,LyricsActivity::class.java))}},LinearLayout.LayoutParams(0,dp(48),1f));opts.addView(rep,LinearLayout.LayoutParams(0,dp(48),1f));c.addView(opts);c.addView(tv("VOLUME",10f,muted,true).apply{setPadding(0,dp(4),0,dp(4))});c.addView(SeekBar(this).apply{max=100;progress=(PlaybackController.volume()*100).toInt();setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,u:Boolean){if(u)PlaybackController.setVolume(p/100f)};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){} })});c.addView(tv("SLEEP TIMER",10f,muted,true).apply{gravity=Gravity.CENTER;background=box(card2,14,true);setPadding(0,dp(12),0,dp(12));setOnClickListener{timerDialog()}});page(c);ui.postDelayed{if(seek.parent!=null)seek.progress=if(PlaybackController.duration()>0)(PlaybackController.position()*1000/PlaybackController.duration()).toInt()else 0},250)}
    private fun formatTime(ms:Long):String{val s=(ms.coerceAtLeast(0)/1000);return "%d:%02d".format(s/60,s%60)}
    private fun eq(){val c=col();c.addView(tv("Equalizer",26f,white,true));c.addView(tv("Real device audio effect",10f,muted).apply{setPadding(0,dp(4),0,dp(12))});val attached=AudioEffects.attach(PlaybackController.audioSessionId());if(!attached)c.addView(tv("Play a song first to enable the hardware equalizer.",11f,muted).apply{setPadding(0,0,0,dp(12))});else{val bands=AudioEffects.bands().toInt();val range=AudioEffects.range();for(i in 0 until bands){val r=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL};r.addView(tv("Band ${i+1}",10f,muted),LinearLayout.LayoutParams(dp(62),-2));val s=SeekBar(this).apply{max=range[1]-range[0];progress=AudioEffects.level(i.toShort())-range[0];progressTintList=android.content.res.ColorStateList.valueOf(violet);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(x:SeekBar?,p:Int,u:Boolean){if(u)AudioEffects.setBand(i.toShort(),(p+range[0]).toShort())};override fun onStartTrackingTouch(x:SeekBar?){};override fun onStopTrackingTouch(x:SeekBar?){} })};r.addView(s,LinearLayout.LayoutParams(0,dp(45),1f));c.addView(r)}};c.addView(tv("PRESETS",12f,white,true).apply{setPadding(0,dp(18),0,dp(8))});listOf("Flat","Bass Boost","Vocal","Acoustic","Electronic").forEach{p->c.addView(tv(p,11f,muted,true).apply{gravity=Gravity.CENTER_VERTICAL;background=box(card,14,true);setPadding(dp(14),0,0,0);setOnClickListener{AudioEffects.setPreset(p);eq()}},LinearLayout.LayoutParams(-1,dp(46)).apply{bottomMargin=dp(6)})};page(c)}
    private fun settings(){val c=col();c.addView(tv("Settings",26f,white,true));libraryCard(c,"Audio","Background playback + media controls","♫"){toast("Media3 background playback is enabled")};libraryCard(c,"Appearance","AMOLED violet theme","◐"){toast("AMOLED theme is active")};libraryCard(c,"Storage","Local files never upload","▣"){toast("Downloads are saved in Music/Spotifusion")};libraryCard(c,"About","Spotifusion 1.2 · Android","i"){toast("Spotifusion")};page(c)}
    private fun timerDialog(){val names=arrayOf("Off","15 minutes","30 minutes","60 minutes","90 minutes");AlertDialog.Builder(this).setTitle("Sleep timer").setItems(names){_,which->sleep?.let(ui::removeCallbacks);if(which==0){sleepEnd=0;getPreferences(0).edit().remove("sleep_end").apply();toast("Timer off")}else{val mins=intArrayOf(0,15,30,60,90)[which];sleepEnd=System.currentTimeMillis()+mins*60000L;getPreferences(0).edit().putLong("sleep_end",sleepEnd).apply();scheduleTimer();toast("Timer set for $mins minutes")}}.show()}
    private fun restoreTimer(){sleepEnd=getPreferences(0).getLong("sleep_end",0L);if(sleepEnd>System.currentTimeMillis())scheduleTimer()else if(sleepEnd>0)getPreferences(0).edit().remove("sleep_end").apply()}
    private fun scheduleTimer(){sleep?.let(ui::removeCallbacks);val delay=(sleepEnd-System.currentTimeMillis()).coerceAtLeast(0L);sleep=Runnable{PlaybackController.pause();sleepEnd=0;getPreferences(0).edit().remove("sleep_end").apply();toast("Sleep timer ended")};ui.postDelayed(sleep!!,delay)}
    override fun onResume(){super.onResume();refreshMini()};override fun onDestroy(){sleep?.let(ui::removeCallbacks);AudioEffects.release();super.onDestroy()};private fun toast(s:String)=Toast.makeText(this,s,Toast.LENGTH_SHORT).show()
}